-- 2. MAXIMUS — HUB  HUB_DISTRIBUTION_CHANNEL [Partner LOB]   [Implemented]
-- Recompute: MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_DISTRIBUTION_CHANNEL|' || PARENT_BK
-- AS VARCHAR))), '')) must equal DISTRIBUTION_CHANNEL_HKEY. collisions = hash keys
-- carrying more than one PARENT_BK. Overlaps DM-K3 (nulls) and DM-K4 (uniqueness) but
-- adds the recompute and length checks.
----------------------------------------------------------------------------------------
with c as (
    select DISTRIBUTION_CHANNEL_HKEY as hkey, count(distinct PARENT_BK) as bks
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_DISTRIBUTION_CHANNEL where startswith(RECORD_SOURCE, 'MAXIMUS_') group by DISTRIBUTION_CHANNEL_HKEY having count(distinct PARENT_BK) > 1
)
select 'MAXIMUS' as project, 'hub' as table_type, 'HUB_DISTRIBUTION_CHANNEL' as table_name,
       count(*) as rows_in_scope,
       count_if(DISTRIBUTION_CHANNEL_HKEY is null) as null_hkey,
       count_if(DISTRIBUTION_CHANNEL_HKEY is not null and length(DISTRIBUTION_CHANNEL_HKEY) <> 16) as wrong_length_hkey,
       count_if(DISTRIBUTION_CHANNEL_HKEY is not null and PARENT_BK is not null and DISTRIBUTION_CHANNEL_HKEY <> MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_DISTRIBUTION_CHANNEL|' || PARENT_BK AS VARCHAR))), ''))) as hkey_not_recomputable,
